function getMechanic(id) {
  const m = MECHANICS.find((x) => x.id === id);
  if (!m) throw new Error(`unknown mechanic "${id}" \u2014 available: ${MECHANICS.map((x) => x.id).join(", ")}`);
  return m;
}
function planMechanicInstall(id, overrides = {}, withDeps = true) {
  const order = [];
  const visit = (x) => {
    const m = getMechanic(x);
    if (withDeps) for (const d of m.needs ?? []) visit(d);
    if (!order.includes(x)) order.push(x);
  };
  visit(id);
  const main2 = getMechanic(id);
  for (const k2 of Object.keys(overrides)) {
    if (!main2.config[k2]) throw new Error(`mechanic ${id} has no config "${k2}" \u2014 options: ${Object.keys(main2.config).join(", ")}`);
    const want = typeof main2.config[k2].default;
    if (typeof overrides[k2] !== want) throw new Error(`config ${k2} must be ${want}`);
  }
  return order.map((mid) => {
    const m = getMechanic(mid);
    const cfg = {};
    for (const [k2, v] of Object.entries(m.config)) cfg[k2] = mid === id && k2 in overrides ? overrides[k2] : v.default;
    return { id: mid, config: cfg, installs: m.install(cfg), isDependency: mid !== id };
  });
}
function listMechanics() {
  return MECHANICS.map((m) => ({
    id: m.id,
    name: m.name,
    category: m.category,
    description: m.description,
    needs: m.needs ?? [],
    usage: m.usage,
    config: Object.fromEntries(Object.entries(m.config).map(([k2, v]) => [k2, { default: v.default, desc: v.desc }]))
  }));
}

