function rng3(seed) {
  let s5 = Math.floor(seed) >>> 0 || 2654435769;
  return () => {
    s5 ^= s5 << 13;
    s5 >>>= 0;
    s5 ^= s5 >>> 17;
    s5 ^= s5 << 5;
    s5 >>>= 0;
    return s5 / 4294967296;
  };
}
var hex2 = (h) => {
  const m = /^#?([0-9a-f]{6})$/i.exec(h.trim());
  if (!m) throw new Error(`bad color "${h}" (use #rrggbb)`);
  const n4 = parseInt(m[1], 16);
  return [n4 >> 16 & 255, n4 >> 8 & 255, n4 & 255];
};
